public class Runner {
    record Case(String label, String input, String expected) {}

    public static void main(String[] args) {
        Case[] cases = new Case[]{
            new Case("\"hello\"", "hello", "olleh"),
            new Case("\"a\"", "a", "a"),
            new Case("\"\"", "", ""),
            new Case("\"racecar\"", "racecar", "racecar")
        };
        for (Case c : cases) {
            try {
                String actual = Solution.reverse(c.input);
                if (c.expected.equals(actual)) {
                    System.out.println("PASS\t" + c.label);
                } else {
                    System.out.println("FAIL\t" + c.label + "\t\"" + c.expected + "\"\t\"" + actual + "\"");
                }
            } catch (Throwable t) {
                System.out.println("ERROR\t" + c.label + "\t" + t.getClass().getSimpleName() + ": " + t.getMessage());
            }
        }
    }
}
